mapper.update:
update now_avatar_tb
set head = #{head},
top = #{top},
bottom = #{bottom},
shoes = #{shoes}
where user_id = #{userId}

update user_tb
set nickname = #{nickname},
elementary_school = #{elementarySchool},
middle_school = #{middleSchool}
high_school = #{highSchool}
where id = #{userId}

mapper.select:
select count(*)
from friend_wait_tb
where receiver_id = #{receiverId} and sender_id = #{senderId}

SELECT u.id, u.name, u.elementary_school, u.middle_school, u.high_school, u.gender
FROM user_tb as u
LEFT JOIN friend_tb as f ON u.id = f.friend_id AND f.user_id = #{userId}
WHERE (u.elementary_school = #{elementarySchool}
OR u.middle_school = #{middleSchool}
OR u.high_school = #{highSchool})
AND u.birth LIKE CONCAT(#{year}, '%')
AND f.friend_id IS NULL
AND u.id <> #{userId};
